import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))
    width = max(expected_width, max(map(len, records), default=0))
    date_pattern = re.compile(
        r"(?:\d{1,2}([/.-])\d{1,2}\1(?:\d{2}|\d{4})"
        r"|\d{4}([/.-])\d{1,2}\2\d{1,2})"
    )

    def labels(row):
        return [value.strip() for value in row]

    def is_label(value):
        return bool(value) and any(char.isalpha() for char in value)

    first_data = next(
        (i for i, row in enumerate(records)
         if row and date_pattern.fullmatch(row[0].strip())),
        len(records),
    )
    candidates = [
        (i, labels(row))
        for i, row in enumerate(records[:first_data])
        if any(value.strip() for value in row)
    ]

    header_indices = set()
    names = []
    for (top_index, top), (bottom_index, bottom) in zip(candidates, candidates[1:]):
        upper = top + [""] * (width - len(top))
        lower = bottom + [""] * (width - len(bottom))
        subcolumns = [i for i, value in enumerate(lower) if value]
        if (
            not upper[0]
            or sum(map(is_label, upper)) < 2
            or len(subcolumns) < 2
            or subcolumns[0] == 0
            or not upper[subcolumns[0]]
            or not all(is_label(lower[i]) for i in subcolumns)
            or not any(not upper[i] for i in subcolumns)
        ):
            continue

        parent = ""
        for group, leaf in zip(upper, lower):
            if group:
                parent = group
            if leaf:
                names.append(f"{parent} - {leaf}" if parent and parent != leaf else leaf)
            else:
                names.append(group)
        header_indices.update((top_index, bottom_index))
        break

    if not header_indices:
        plausible = [
            (i, row) for i, row in candidates
            if row and is_label(row[0]) and sum(map(is_label, row)) >= 2
        ]
        if plausible:
            header_index, names = max(
                plausible, key=lambda item: sum(map(is_label, item[1]))
            )
            header_indices.add(header_index)

    columns = []
    used = set()
    for i in range(width):
        base = (names[i] if i < len(names) else "") or f"column_{i + 1}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        used.add(name)
        columns.append(name)

    return {
        "columns": columns,
        "rows": [
            row + [""] * (width - len(row))
            for i, row in enumerate(records)
            if i not in header_indices
        ],
    }
